) AS (
  VALUES 
    (472::BIGINT, 'Clases muy aburridas, pero a todo le pone 100 y se pasa muy facil. Super buena persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-10T00:00:00+00:00'::TIMESTAMPTZ, '16cf7d4e7e3f4358d5881fbe0604dd5d7b0c97b69507c54aa6f9d7048210ca6c'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'Es buena persona. Normalmente enreda las preguntas de los quices y exámenes en tecnicismos. Busque un buen grupo, para el proyecto y puede que algún exámen'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Brinda apoyo']::TEXT[], '2026-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'a5f09ada22b7a02c07c7476276377f412d7d149265fe8e0604f3792747e3dfd8'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Si ud entrega los trabajos bien el curso se pasa solo. Ella es un amor aunque las clases son un toque aburridas jaja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '23e1b7210838510607ad78fcf76a0b92d7329eefba59c5b820d5974674c6feae'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Un amor de persona, solo hay que hacer los trabajos que deja y el curso ella lo hace para que no sea pesado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, '463554e08bb6bf09b7c07c9a88efc510a327440f71c29436275ca0725c64ed25'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Clase fácil, exámenes y tareas en grupos y se hacen en la casa y por el Gap. Meta con ella, va a pasar fácil si hace todo y le pone un poco.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'a46f8a52232db68ff971243744b877ba78a0ea2f7fdde3e457db13ac31e3fa45'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Facil el curso, a todo le pone 100. La asistencia es obligatorio, pero no le importa si pone atencion o si esta haciendo otra cosa en clase. Pocas tareas y examenes, todo por el gaap y puro marque con x'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, '98fa2a7a1a24b687af03c61e9d330688548d9f011b931ec249d6413649850a84'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Buena profesora, tome apuntes y pasa el curso con buena nota, casi todas las evaluaciones son grupales, el proyecto es sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Pocos exámenes']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c0be4cf55689a34fbbc234af8f0ef7d1a9595d697a277a169dba505dbb105b4d'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'La verdad la profe es muy buena, la clase es un poco rutinaria pero por cuestiones del curso.Ella super agradable, instrucciones claras y permite obtener puntos por participacion.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, '5e3a9d8b85d8344218b74db5b9a0c670c1e43e34846ece8d2457e99980c2362c'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'Su clase básicamente es pararse y leer 70 diapositivas, super aburrida la clase, lleve una almohada porque tenga claro que se va a quedar dormido ????, es buena gente pero para dar clases no sirve'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-09-27T00:00:00+00:00'::TIMESTAMPTZ, 'f35697ec0c85d69042b42a064235fc8625009546f9a88f79a49066de9e133fb3'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'Como persona es muy agradable pero como profesora deja que desear, sus clases son ella leyendo presentaciones de power point, 0 dinamica, sus clases son demasiado largas y aburridas.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '94debc48f3c94b6b765aa23e23c1a77260a15a37520c7c06e3748f7c52021cef'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'La clase es muy tediosa, es solo ella leyendo presentaciones, no se le entiende bien. Además califica muy mal, baja muchos puntos por cosas insignificantes, como que el portafolio no le parece atractivo o si usamos solo 5 fuentes, cuando ella eso fue lo que pidió. Es buena persona, pero mala profe.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, '2d24b38a3adf49e1cbb1649adef3780fc508736c7b264bbae49447b30628e11d'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'La verdad es muy buena persona pero como profesora es terrible, es ella leyendo la un ppt toda la clase, cuesta mucho interesarse en la clase x que ella no lo hace dinámico y luego eso se lo saca en cara a uno. Además hace examenes de pura respuesta corta y quita puntos x nada en las evaluaciones.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'd3d2d9ea6734c5d86428cb0ca6c3e89d8e23fd9cf3331899db5fea319af9b6cd'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'La materia como tal no es interesante, por lo que la clase es un toque pesada pero la profe es muy relajada y explica bien. Algunas clases las hace asincrónicas y deja el material para leer en la casa. Los exámenes son un toque confusos pero se pasan bien, y los quizzes igual, procuren participar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '8c83cbdb067cca1ba2f17ece5b38da7269013da5d5f71e63281031535829e011'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'El curso va a ser aburrido con cualquier profe. Pero si tiene chance, matricule con ella sin duda. Explica claro, es muy organizada, deja trabajos que se sacan en un día si tiene un buen grupo, y se pasa fácil. La mejor para este curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, '271bcc06f4c57a43557aac3ef1039fafd8c070fcd147383ccdf4f0ff7533a6e4'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Las clases son un poco cansadas no por la profe en si, sino por el tiempo que dura la clase (Aproximadamente 3 horas desde las 7 am). Por otro lado la profe explica demasiado bien, tiene presentaciones muy claras, coherentes y concisas. Casi todo el semestre se trabaja en grupos, matricule con ella.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Clases excelentes']::TEXT[], '2023-11-20T00:00:00+00:00'::TIMESTAMPTZ, '1387c3212ea3df78c3059083bc26682b8dcb4bd49bb06af59fe3b935c8867f7d'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Se pasa fácil, pero como todo el mundo se le iba ahora pasa lista al final, así que anclado toda la clase que es bastante aburrida, es ella leyendo un PPT. No se aprende nada, todo es en el GAAP, un proyecto que se saca rápido, un curso más de relleno, casi no le quita tiempo y la profe lo sabe'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1f0e21fd092fcd3b114c9c7fb01105f2f8e8004fff6b55828d1200d3b20fcdd7'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-19T00:00:00+00:00'::TIMESTAMPTZ, '35ecec5c92ba851a48c3bf21fca499bbebb920ab51815c5aebdad83b128bce78'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'La profe es muy buena, las clases son puras presentaciones de power point, todas las tareas, exámenes y el proyecto final es en grupo el cual se elige desde la primera clase y no se puede cambiar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2023-04-25T00:00:00+00:00'::TIMESTAMPTZ, 'd4d7bcb92406dfd38ff381e8ff82c729cef80ca1a83514bba0dfe9c91fbc2663'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Re fácil, todas las evaluaciónes son el gaap, las clases son una tortura, demasiado aburridas, es imposible no dormirse, clases largas, todo mundo deja de ir como en semana 4 pero igual se pasa, no es fundamental ir porque todo lo de las evaluaciónes lo sube al tec digital.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-06T00:00:00+00:00'::TIMESTAMPTZ, '5891205a206f9f3b8aa11dd5e223ec0b76d5befd33b3684330d3796ccc17e9f2'::TEXT, ARRAY[4053]::BIGINT[]),
    (472::BIGINT, 'Es un amor, explica muy claro todo, atiende dudas. Lo malo es que las clases son muuuuy aburridas, la gente deja de ir. Todo es grupal, deja muchos gaaps'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '802f6e0ccafab4bf272a1371a7564d62ca4057fb3f3d3e5ed646221cd182221e'::TEXT, ARRAY[3087]::BIGINT[]),
    (472::BIGINT, 'Excelente profesora, explica los temas de la manera más clara posible y se preocupa por el aprendizaje del estudiante. Realiza muchos trabajos, la mayoría de ellos de manera grupal, son pero son súper sencillos, básicamente con dichos trabajos se gana el curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Muchos proyectos grupales']::TEXT[], '2022-07-22T00:00:00+00:00'::TIMESTAMPTZ, '28bbcae80a5c89d79b998a0432e86cbc32a70a55999978086d476853cf4c090a'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Buena profe. Se nota su interés por el tema, explica bien, aclara dudas, y califica justamente. Con un buen grupo de trabajo el curso se pasa solo. Lo único es que hace las clases muy largas y deja muchos trabajos. Aunque hace el curso algo tedioso, esta profe hace que se pase fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1da50b0cd2153f8b68a4abb95c4c20c3b57400632138f21e86aa5ef0c1f720d4'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Muy buena profe, se le nota el interés y la pasión por la materia, además a pesar de que la gente no participa, ella es muy amable. El curso en sí es muy sencillo apenas unos cuantos trabajos y exámenes mitad GAAP y mitad grupal. Lo único es que por la falta de participación la clase se vuelve larga'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '0aecb55cefc711d01e09a2f4bbf9b66e3e1efd77880caff6d50242fb476e23cf'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Es buena gente, las clases son algo largas pero manejables, deja una que otra actividad algunas semanas del semestre pero todo es en grupo y fácil. Las diapositivas si son eternas entonces cuesta un poco memorizar tanta materia para los exámenes, pero en general son pasables.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '837ca40451af7acbbe2a644e52e2c24a1faebb8a225e23d31c8709b319ea0fd2'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'No la recomiendo porque no ayuda en lo absoluto a contestar dudas, nunca me contesto un mensaje o un correo. A veces simplemente no daba la clase, es un poco vaga y los temas no son tan claros.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, 'f4939b2b331766d4c66ffa4511f4b87cf0a03207ce403d4e74d888502be3003b'::TEXT, ARRAY[4769, 1182, 637, 1999, 636, 1726, 640]::BIGINT[]),
    (472::BIGINT, 'Una profe muy amable y buena persona. Al explicar no solo lee diapositivas si no que explica de su experiencia y se nota su dedicación al enseñar. Recomiendo se haga de un buen grupo de trabajo, ya que el curso depende un poco de eso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'e0155f1064ae21815234bd1194a2bbea4b755ead805152302bbd800d5e23dcc0'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Consigase un buen grupo y el curso se pasa solo, incluso sin meterse a clases hace los exámenes, es muy intuitivo, la mayoría. Por la profe es la mejor, muy buena gente y amable :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'dfe8d3111cece389eade30933b4f0a1942f615be7b49e5c971d1911c01dbbe10'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Un curso pesado pero la profe lo hace muy sencillo. Da varios intentos para hacer quices y exámenes, por lo que se puede revisar la materia. Las clases sincrónicas son pesadas pero las combina dando lecciones asíncronas interactivas. El examen es mitad grupal y mitad individual.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '9d613151259cf9e5e04eb5d2d1ccad8c021318f3eba091ac6b6cb675a59d2c67'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Se lo resumo así: un amor de profesora, ayuda a los estudiantes, se preocupa y evalúa súper claro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'f880fef9aedba9e929fda0f843c2e833a15a997d951dd918ec1430132797230e'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'La profe es demasiado ordenada, es super linda, escucha a los estudiantes y se preocupa por ellos, todo es en grupo, entonces hágase un buen grupo, deja muchos trabajos pero explica con claridad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '542131aaec5d5a06ecb62bbf2e5114377a12832b3fc92b2d0912f1cf6ae0d07d'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Se adaptó muy bien a lo virtual, es muy ordenada y deja bastante tiempo para hacer trabajos. Eso si, todo es en grupos, entonces trate de conseguir un buen grupo y el curso se pasa solo. Lea bien las rubricas y con eso está sobrado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '06d0116ed00018caa00e69be03e55a0eeb15c96cf31f280688d2af33c740dd7d'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'En virtual fue sencillo. Hay que trabajar, pero nada del otro mundo. Es muy organizada y da bastante tiempo para los trabajos. Todo fue en grupo. Recomendaciones: tenga un buen grupo de trabajo y lea las instrucciones ( rubricas en tec digital) para que no pierda puntos por detalles'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '9e81d6b660d8f7cdb5a833e6c9f83ec50c88af3633b85355d48ab4e565601d1b'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Excelente profesora, maneja muy bien los recursos virtuales, se interesa porque los estudiantes aprendan, es amable y se ve que le gusta lo que hace. De fijo pasa y aprende. Y es muy organizada.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'de0acd417ee9acb40a26773a14bee0c8f62b04b32b5bb4fc3ee801312de1d474'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Excelente profesora, explica bien aunque las clases son aburridas. Si es virtual el curso se hace mucho maás sencillo. Deja bastante trabajos pero son fáciles. El curso es puramente teórico. La recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'ffa6397031fa3f3e94ce6db4c5a8454dd6623e00c84c7d9183ee6c087cf9d534'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Muy buena, evaluaciones que se entienden y se sacan fácil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '9cbb982917824fb5f8b8c06ec2302bf9c20376b3a56ff3307bf1f68a117b5be6'::TEXT, ARRAY[155, 3105]::BIGINT[]),
    (472::BIGINT, 'Súper buena gente, uno aprende y califica justo con instrucciones claras. Hay que trabajar pero las entregas son sencillas. En modalidad virtual todo fue en grupos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '12884deadc2eb970cd71a5a1818865d2d60278c89021fc4a50447c13d1805bf9'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '4e7548772de8fdc55cd0bddeb3d12cd443fdafd27a772af95bcb8b1b16761d65'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Muy responsable, tareas y proyectos super claros, no lo dude! Busque un buen equipo de trabajo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Clases excelentes']::TEXT[], '2020-08-12T00:00:00+00:00'::TIMESTAMPTZ, '67b482433fb596aa52c542f41219c81673e402b2b1376d9c88f1de0f8eedc17e'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Facil de pasar por la materia, pero si se aprende mucho.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2019-06-16T00:00:00+00:00'::TIMESTAMPTZ, '8811465ae36db73d060857a823bdc5adffc20a71806db76e7125c0b0072fb3cf'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Es una buena profesora, no deja trabajos tan duros como otros profes. Se ve que no tiene ganas de molestar a los estudiantes, más bien intenta que uno aprenda algo. Es muy buena gente y organizada con los trabajos. Todo es grupal.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2019-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ee1966c9f20400245548d2cb74cffaf745eceb649cfa631350c067341471b7f8'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'El curso es muy fácil, pero la profesora es un bostezo. Se molesta si uno hace algo de otro curso y no queda nada más que poner atención a menos de que uno se quede dormido jajajaja'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-28T00:00:00+00:00'::TIMESTAMPTZ, '90de1efdcfc96d481527297c14822a12896effb47d81ca0dd579db3ee26a9045'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'Un curso sencillo con una profesora muy buena nota. Dejó en todo el semestre 3 tareas y los exámenes son muy sencillos. Además el proyecto final no es complicado, solo es de hacerlo con tiempo. Por otra parte, el comentario de abajo nada que ver...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'babd6e228d5a9f93221adf93142b06bdff3c26e35cfc667dfc85a5cea0e3decb'::TEXT, ARRAY[155]::BIGINT[]),
    (472::BIGINT, 'La mae es muy mala, se le mete el agua feisimo, hace unos exámenes demasiados específicos en respuesta corta, no la recomiendo para nada además que no se aprende nada'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-10-24T00:00:00+00:00'::TIMESTAMPTZ, '63ec0d61a8c9eac1227e3f34077632506e3ef514db3e30ba1109b6ad64a6f7e0'::TEXT, ARRAY[998]::BIGINT[]),
    (472::BIGINT, 'Es una buena profesora, quien explica con mucha paciencia y de manera clara. Deja pocas tareas que son realmente sencillas y los exámenes se hacen en grupos. Un punto importante que hay que tomar en cuenta es no faltar a clases más de dos veces, si no automáticamente pierde el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'f8baae8bd7dabceae886edb400596d63c4eb5b373f73017ff5e9f1b65594711e'::TEXT, ARRAY[155]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
